PDFjs: {
  onBeforeAddons(manager, param) {
    if ("Enabled" in param) {
      lazy.PoliciesUtils.setAndLockPref("pdfjs.disabled", !param.Enabled);
    }
    if ("EnablePermissions" in param) {
      lazy.PoliciesUtils.setAndLockPref(
        "pdfjs.enablePermissions",
        param.EnablePermissions
      );
    }
  },
},
